/** Animated track with driver dots positioned around the circuit. */
const RaceTrackViz: React.FC<{
  circuitId: string;
  standings: DriverLapState[];
  userDriverId: string;
  totalLaps: number;
  currentLap: number;
  safetyCarActive: boolean;
  vscActive: boolean;
  paused?: boolean;
}> = ({ circuitId, standings, userDriverId, totalLaps, currentLap, safetyCarActive, vscActive, paused = false }) => {
  const trackInfo = TRACK_REGISTRY.find(t => t.id === circuitId);
  const trackPathRef = useRef<SVGPathElement | null>(null);
  const overlayRef = useRef<SVGSVGElement | null>(null);
  // Callback-ref maps: populated once on mount, O(1) lookup per frame
  const circleMapRef = useRef<Map<string, SVGCircleElement>>(new Map());
  const labelMapRef = useRef<Map<string, SVGTextElement>>(new Map());
  // Animation start time : advances only while not paused, so position is held on pause
  const animStartRef = useRef<number>(Date.now());
  const pausedAtRef = useRef<number | null>(null); // elapsed ms when pause started
  const animRef = useRef<number | null>(null);
  // Keep latest standings accessible inside the rAF closure without re-subscribing
  const standingsRef = useRef(standings);
  standingsRef.current = standings;
  // Keep paused flag accessible in rAF closure without re-subscribing
  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  // Visual lap duration is decoupled from the data update interval.
  // Cars complete one full circuit in VISUAL_LAP_MS regardless of how fast
  // the race data advances (real F1 lap ~90s compressed 60x → 1.5s data pace,
  // but we want the cars to be visibly moving at ~14s per circuit).
  const VISUAL_LAP_MS = 14_000;

  // Continuous animation loop : moves dots imperatively so React doesn't re-render at 60 fps.
  // When paused, the loop keeps running but skips DOM updates, freezing cars in place.
  useEffect(() => {
    const tick = () => {
      if (!pausedRef.current) {
        // If we were paused, shift animStartRef forward by the paused duration so
        // cars resume from the exact position they froze at.
        if (pausedAtRef.current !== null) {
          animStartRef.current += Date.now() - animStartRef.current - pausedAtRef.current;
          pausedAtRef.current = null;
        }
        const pathEl = trackPathRef.current;
        if (pathEl) {
          const totalLength = pathEl.getTotalLength();
          // Continuously cycle 0→1 every VISUAL_LAP_MS regardless of lap counter
          const elapsed = Date.now() - animStartRef.current;
          const lapFrac = (elapsed % VISUAL_LAP_MS) / VISUAL_LAP_MS;
          const S = standingsRef.current;
          const n = S.length || 20;
          for (const d of S) {
            // P1 is furthest ahead (gapFrac → highest), P-last is at 0
            const gapFrac = (n - d.position) / n;
            const frac = (lapFrac + gapFrac) % 1.0;
            const pt = pathEl.getPointAtLength(frac * totalLength);
            const circle = circleMapRef.current.get(d.driver_id);
            if (circle) {
              circle.setAttribute('cx', pt.x.toFixed(1));
              circle.setAttribute('cy', pt.y.toFixed(1));
            }
            const label = labelMapRef.current.get(d.driver_id);
            if (label) {
              label.setAttribute('x', pt.x.toFixed(1));
              label.setAttribute('y', (pt.y + 12).toFixed(1));
            }
          }
        }
      } else {
        // Record the elapsed ms at the moment we first noticed the pause
        if (pausedAtRef.current === null) {
          pausedAtRef.current = Date.now() - animStartRef.current;
        }
      }
      animRef.current = requestAnimationFrame(tick);
    };
    animRef.current = requestAnimationFrame(tick);
    return () => { if (animRef.current !== null) cancelAnimationFrame(animRef.current); };
  }, []); // empty: all mutable state accessed via refs

  return (
    <div className="relative rounded-xl overflow-hidden border" style={{ borderColor: 'var(--border-color)', backgroundColor: '#0A0A0A' }}>
      {/* Header strip */}
      <div className="flex items-center justify-between px-4 py-2 border-b" style={{ borderColor: 'var(--border-color)' }}>
        <div className="flex items-center gap-2">
          <Radio className="w-3.5 h-3.5 text-red-500 animate-pulse" />
          <span className="text-xs font-mono font-bold uppercase tracking-widest text-white/60">
            LAP {currentLap} / {totalLaps}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {safetyCarActive && (
            <motion.span
              animate={{ opacity: [1, 0.4, 1] }}
              transition={{ duration: 0.8, repeat: Infinity }}
              className="text-[9px] font-black px-2 py-0.5 rounded bg-yellow-400 text-black uppercase tracking-wider"
            >
              SAFETY CAR
            </motion.span>
          )}
          {vscActive && !safetyCarActive && (
            <motion.span
              animate={{ opacity: [1, 0.4, 1] }}
              transition={{ duration: 0.8, repeat: Infinity }}
              className="text-[9px] font-black px-2 py-0.5 rounded bg-orange-400 text-black uppercase tracking-wider"
            >
              VIRTUAL SC
            </motion.span>
          )}
          <span className="text-[9px] font-mono text-white/30 uppercase">
            {trackInfo?.name ?? circuitId}
          </span>
        </div>
      </div>

      {/* SVG Track */}
      <div className="flex items-center justify-center py-4 px-6">
        <div className="relative" style={{ width: 320, height: 220 }}>
          <TrackDisplay
            trackId={circuitId}
            width={320}
            height={220}
            strokeColor="rgba(255,255,255,0.45)"
            strokeWidth={3}
            showStartFinish
            animated={false}
            pathRef={trackPathRef}
          />
          {/* Driver dots : positions driven imperatively by the rAF loop above */}
          <svg
            ref={overlayRef}
            className="absolute inset-0"
            width={320}
            height={220}
            viewBox="0 0 300 200"
            style={{ pointerEvents: 'none' }}
          >
            {standings.map((d) => {
              const isUser = d.driver_id === userDriverId;
              const teamColor = (TEAM_COLORS as any)[d.team] ?? '#888';
              return (
                <g key={d.driver_id}>
                  <title>{`P${d.position} ${d.display_name}`}</title>
                  <circle
                    ref={(el) => {
                      if (el) circleMapRef.current.set(d.driver_id, el);
                      else circleMapRef.current.delete(d.driver_id);
                    }}
                    cx={0}
                    cy={0}
                    r={isUser ? 6 : 4}
                    fill={isUser ? COLORS.accent.red : teamColor}
                    stroke={isUser ? '#fff' : 'rgba(255,255,255,0.3)'}
                    strokeWidth={isUser ? 2 : 1}
                    style={isUser ? { filter: 'drop-shadow(0 0 4px #E10600)' } : undefined}
                  />
                  {isUser && (
                    <text
                      ref={(el) => {
                        if (el) labelMapRef.current.set(d.driver_id, el);
                        else labelMapRef.current.delete(d.driver_id);
                      }}
                      x={0}
                      y={12}
                      textAnchor="middle"
                      fontSize={6}
                      fill="#fff"
                      fontWeight="bold"
                    >
                      {d.code?.slice(0, 3)}
                    </text>
                  )}
                </g>
              );
            })}
          </svg>
        </div>
      </div>

      {/* Mini driver legend */}
      <div className="px-4 pb-3 grid grid-cols-4 gap-1">
        {standings.slice(0, 8).map(d => {
          const teamColor = (TEAM_COLORS as any)[d.team] ?? '#888';
          const isUser = d.driver_id === userDriverId;
          return (
            <div key={d.driver_id} className={`flex items-center gap-1.5 px-1.5 py-1 rounded ${isUser ? 'ring-1 ring-red-600/50' : ''}`}
              style={{ backgroundColor: isUser ? 'rgba(225,6,0,0.08)' : 'transparent' }}>
              <span className="text-[8px] font-mono text-white/30 w-3">{d.position}</span>
              <span className="w-1.5 h-1.5 rounded-full flex-shrink-0" style={{ backgroundColor: teamColor }} />
              <span className="text-[8px] font-mono font-bold truncate" style={{ color: isUser ? COLORS.accent.red : 'rgba(255,255,255,0.6)' }}>
                {d.code ?? d.display_name?.slice(0, 3).toUpperCase()}
              </span>
              {compoundDot(d.compound, 6)}
            </div>
          );
        })}
      </div>
    </div>
  );
};

